type Completion =
  | { kind: "ok"; reply: Reply }
  | { kind: "err"; error: Error };

const reply: Awaited<Promise<Reply>> = await call(request);   // token = the promise
function dispatch(c: Completion) {
  switch (c.kind) {                    // exhaustive by construction
    case "ok": return apply(c.reply);
    case "err": return report(c.error);
  }
}

const handlers = new Map<RequestId, (c: Completion) => void>();
function dispatch(id: RequestId, c: Completion) {
  const h = handlers.get(id);
  if (!h) throw new Error(`unknown request ${id}`);
  handlers.delete(id);                 // exactly-once semantics, enforced by hand
  h(c);
}

